'use strict';
const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { URL } = require('url');
function makeRuntime({root,registry}){
  const dataDir=path.join(root,'data-runtime'); fs.mkdirSync(dataDir,{recursive:true});
  const profileFile=path.join(dataDir,'connector-profiles.json');
  const overrides={
    marktplaats:{
      id:'marktplaats',naam:'Marktplaats',categorie:'automotive_marktplaats',connection_mode:'oauth2',
      auth_strategy:'oauth2_authorization_code',base_url:'https://api.marktplaats.nl',
      oauth:{authorization_url:'https://auth.marktplaats.nl/accounts/oauth/authorize',token_url:'https://auth.marktplaats.nl/accounts/oauth/token',scope:'',client_id_field:'client_id',client_secret_field:'client_secret'},
      health:{path:'/categories',method:'GET',accept:'application/json'},
      sync:{path:'/search',method:'GET'},
      credential_fields:[{key:'client_id',label:'Client ID',secret:false},{key:'client_secret',label:'Client secret',secret:true}],
      capabilities:['connect','oauth','test','sync','search','data_ingest','tenant_credentials']
    },
    mobile_de:{
      id:'mobile_de',naam:'mobile.de',categorie:'automotive_marktplaats',connection_mode:'credentials',auth_strategy:'basic',
      base_url:'https://services.mobile.de',health:{path:'/search-api/search?ps=1',method:'GET',accept:'application/vnd.de.mobile.api+json'},
      sync:{path:'/search-api/search',method:'GET'},
      credential_fields:[{key:'username',label:'API username',secret:false},{key:'password',label:'API password',secret:true}],
      headers:{accept:'application/vnd.de.mobile.api+json'},
      capabilities:['connect','test','sync','search','seller_api','lead_api','insights_api','ad_stream','data_ingest','tenant_credentials']
    }
  };
  function infer(id,s={}){
    const auth=String(s.auth||'configurable').toLowerCase(); let strategy='api_key_header',mode='credentials';
    if(auth==='public'||auth==='public_or_api_key'){strategy=auth==='public'?'public':'api_key_header';mode='direct'}
    else if(auth.includes('oauth')){strategy='oauth2_authorization_code';mode='oauth2'}
    else if(auth.includes('basic')||auth.includes('credentials'))strategy='basic';
    else if(auth.includes('webhook'))strategy='webhook';
    else if(auth.includes('token'))strategy='bearer';
    const credential_fields=strategy==='basic'?[{key:'username',label:'Username',secret:false},{key:'password',label:'Password',secret:true}]:strategy==='oauth2_authorization_code'?[{key:'client_id',label:'Client ID',secret:false},{key:'client_secret',label:'Client secret',secret:true}]:[{key:'api_key',label:'API key / token',secret:true}];
    return {id,naam:s.naam||id,categorie:s.categorie||'overig',connection_mode:mode,auth_strategy:strategy,base_url:'',health:{path:'',method:'GET'},sync:{path:'',method:'GET'},headers:{},credential_fields,modules:s.modules||[],capabilities:Array.from(new Set(['connect','test','sync','tenant_credentials','data_ingest',...(s.capabilities||[])]))};
  }
  function loadOverrides(){try{return JSON.parse(fs.readFileSync(profileFile,'utf8'))}catch{return {}}}
  function saveOverrides(v){fs.writeFileSync(profileFile,JSON.stringify(v,null,2))}
  function profiles(){const custom=loadOverrides();const out={};for(const [id,s] of Object.entries(registry||{}))out[id]={...infer(id,s),...s,...(overrides[id]||{}),...(custom[id]||{})};for(const [id,p] of Object.entries(custom))if(!out[id])out[id]={...p,id};return out}
  function tenantKey(c){return crypto.createHash('sha256').update(`${c.tenant_id}:${c.dealer_id}`).digest('hex').slice(0,40)}
  function secretFile(c,id){return path.join(dataDir,`connector-${tenantKey(c)}-${String(id).replace(/[^a-z0-9_-]/gi,'_')}.json`)}
  function encKey(){const raw=process.env.FOUNDLY_ENCRYPTION_KEY||process.env.GOOGLE_TOKEN_ENCRYPTION_KEY||'';return raw?crypto.createHash('sha256').update(raw).digest():null}
  function seal(v){const k=encKey();if(!k)return {encrypted:false,data:v};const iv=crypto.randomBytes(12),cipher=crypto.createCipheriv('aes-256-gcm',k,iv);const b=Buffer.concat([cipher.update(JSON.stringify(v),'utf8'),cipher.final()]);return {encrypted:true,iv:iv.toString('base64'),tag:cipher.getAuthTag().toString('base64'),data:b.toString('base64')}}
  function unseal(x){if(!x)return {};if(x.encrypted===false)return x.data||{};const k=encKey();if(!k)throw new Error('FOUNDLY_ENCRYPTION_KEY ontbreekt');const d=crypto.createDecipheriv('aes-256-gcm',k,Buffer.from(x.iv,'base64'));d.setAuthTag(Buffer.from(x.tag,'base64'));return JSON.parse(Buffer.concat([d.update(Buffer.from(x.data,'base64')),d.final()]).toString('utf8'))}
  function readConfig(c,id){try{return unseal(JSON.parse(fs.readFileSync(secretFile(c,id),'utf8')))}catch{return {}}}
  function writeConfig(c,id,v){fs.writeFileSync(secretFile(c,id),JSON.stringify(seal(v),null,2))}
  function removeConfig(c,id){try{fs.unlinkSync(secretFile(c,id))}catch{}}
  function ctx(req,b={}){return {tenant_id:String(b.tenant_id||req.headers['x-foundly-tenant']||'default'),dealer_id:String(b.dealer_id||req.headers['x-foundly-dealer']||'default')}}
  function body(req){return new Promise((resolve,reject)=>{let s='';req.on('data',c=>{s+=c;if(s.length>2e6)reject(new Error('Payload te groot'))});req.on('end',()=>{try{resolve(s?JSON.parse(s):{})}catch{reject(new Error('Ongeldige JSON'))}});req.on('error',reject)})}
  function send(res,status,obj){res.writeHead(status,{'content-type':'application/json; charset=utf-8','cache-control':'no-store'});res.end(JSON.stringify(obj))}
  function origin(req){const proto=req.headers['x-forwarded-proto']||'https',host=req.headers['x-forwarded-host']||req.headers.host;return `${proto}://${host}`}
  function stateSecret(){return process.env.FOUNDLY_OAUTH_STATE_SECRET||process.env.GOOGLE_OAUTH_STATE_SECRET||process.env.FOUNDLY_ENCRYPTION_KEY||'foundly-dev-state'}
  function signState(o){const raw=Buffer.from(JSON.stringify(o)).toString('base64url'),sig=crypto.createHmac('sha256',stateSecret()).update(raw).digest('base64url');return `${raw}.${sig}`}
  function parseState(s){const [raw,sig]=String(s||'').split('.'),exp=crypto.createHmac('sha256',stateSecret()).update(raw||'').digest('base64url');if(!raw||!sig||!crypto.timingSafeEqual(Buffer.from(sig),Buffer.from(exp)))throw new Error('Ongeldige OAuth state');return JSON.parse(Buffer.from(raw,'base64url').toString('utf8'))}
  function merged(id,c){const p=profiles()[id];if(!p)return null;const cfg=readConfig(c,id);return {...p,...(cfg.profile_overrides||{}),_credentials:cfg.credentials||{},_tokens:cfg.tokens||{}}}
  function authHeaders(p){const c=p._credentials||{},t=p._tokens||{},h={...(p.headers||{})};if(p.health?.accept&&!h.accept)h.accept=p.health.accept;switch(p.auth_strategy){case'basic':if(c.username||c.password)h.authorization=`Basic ${Buffer.from(`${c.username||''}:${c.password||''}`).toString('base64')}`;break;case'bearer':if(t.access_token||c.access_token||c.api_key)h.authorization=`Bearer ${t.access_token||c.access_token||c.api_key}`;break;case'api_key_header':{const key=c.api_key||c.access_token;if(key)h[p.auth_header||'authorization']=(p.auth_prefix===undefined?'Bearer ':p.auth_prefix)+key;break;}default:if(t.access_token)h.authorization=`Bearer ${t.access_token}`}return h}
  async function status(c,id){const p=merged(id,c);if(!p)return {id,configured:false,connected:false,error:'Onbekende connector'};const cr=p._credentials||{},tk=p._tokens||{};const required=(p.credential_fields||[]).filter(f=>f.required!==false);const configured=p.auth_strategy==='public'||Boolean(tk.access_token)||required.every(f=>Boolean(cr[f.key]))||Boolean(cr.api_key||cr.username||cr.client_id||p.base_url);
    const out={id,name:p.naam||id,category:p.categorie||'overig',connection_mode:p.connection_mode,auth_strategy:p.auth_strategy,configured,connected:false,capabilities:p.capabilities||[],error:null};
    if(!configured)return out;if(p.auth_strategy==='webhook'){out.connected=true;return out}const url=(p.base_url||'').replace(/\/$/,'')+(p.health?.path||'');if(!url){out.error='Base URL/health endpoint nog niet ingesteld';return out}
    try{const r=await fetch(url,{method:p.health?.method||'GET',headers:authHeaders(p)});out.connected=r.ok;if(!r.ok)out.error=`HTTP ${r.status}`;}catch(e){out.error=e.message}return out}
  async function oauthStart(req,res,id,u){const c=ctx(req),p=merged(id,c);if(!p)return send(res,404,{error:'Onbekende connector'});const o=p.oauth||{},cr=p._credentials||{};if(!o.authorization_url||!o.token_url)return send(res,409,{error:'OAuth endpoints ontbreken in connectorprofiel; vul ze eenmalig in via PROFIEL'});if(!cr.client_id)return send(res,409,{error:'Client ID ontbreekt'});const redirect=`${origin(req)}/api/connector-runtime/oauth/${encodeURIComponent(id)}/callback`,state=signState({...c,id,return_to:u.searchParams.get('return_to')||'/',ts:Date.now()});const q=new URLSearchParams({response_type:'code',client_id:cr.client_id,redirect_uri:redirect,state});if(o.scope)q.set('scope',Array.isArray(o.scope)?o.scope.join(' '):o.scope);for(const [k,v] of Object.entries(o.authorize_params||{}))q.set(k,String(v));res.writeHead(302,{location:`${o.authorization_url}?${q}`});res.end()}
  async function oauthCallback(req,res,id,u){try{const st=parseState(u.searchParams.get('state')),p=merged(id,st),o=p.oauth||{},cr=p._credentials||{},code=u.searchParams.get('code');if(!code)throw new Error(u.searchParams.get('error_description')||u.searchParams.get('error')||'Authorization code ontbreekt');const redirect=`${origin(req)}/api/connector-runtime/oauth/${encodeURIComponent(id)}/callback`;const form=new URLSearchParams({grant_type:'authorization_code',code,client_id:cr.client_id,client_secret:cr.client_secret||'',redirect_uri:redirect});const r=await fetch(o.token_url,{method:'POST',headers:{'content-type':'application/x-www-form-urlencoded'},body:form});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error_description||j.error||`Token HTTP ${r.status}`);const old=readConfig(st,id);writeConfig(st,id,{...old,tokens:{...j,obtained_at:Date.now(),expires_at:j.expires_in?Date.now()+Number(j.expires_in)*1000:null}});res.writeHead(302,{location:`${st.return_to||'/'}${String(st.return_to||'/').includes('?')?'&':'?'}connector=${encodeURIComponent(id)}&connected=1`});res.end()}catch(e){res.writeHead(302,{location:`/?connector=${encodeURIComponent(id)}&error=${encodeURIComponent(e.message)}`});res.end()}}
  async function sync(c,id){const p=merged(id,c);if(!p)throw new Error('Onbekende connector');const ep=p.sync||{};if(!p.base_url||!ep.path)throw new Error('Sync endpoint nog niet ingesteld');const r=await fetch(p.base_url.replace(/\/$/,'')+ep.path,{method:ep.method||'GET',headers:authHeaders(p)});const text=await r.text();if(!r.ok)throw new Error(`Sync HTTP ${r.status}: ${text.slice(0,180)}`);let data;try{data=JSON.parse(text)}catch{data={raw:text}}return {ok:true,id,received_at:new Date().toISOString(),data}}
  async function handle(req,res,u){
    const m=u.pathname.match(/^\/api\/connector-runtime\/(profile|config|test|sync)\/([^/]+)$/);
    if(u.pathname==='/api/connector-runtime/profiles'&&req.method==='GET')return send(res,200,{ok:true,profiles:Object.values(profiles()),total:Object.keys(profiles()).length});
    if(u.pathname==='/api/connector-runtime/profiles'&&req.method==='POST'){const b=await body(req);if(!b.id||!b.naam)return send(res,400,{error:'id en naam zijn verplicht'});const all=loadOverrides();all[b.id]={...b,id:b.id};saveOverrides(all);return send(res,201,{ok:true,profile:all[b.id]})}
    if(m&&m[1]==='profile'){
      const id=decodeURIComponent(m[2]);if(req.method==='GET'){const p=profiles()[id];return p?send(res,200,{ok:true,profile:p}):send(res,404,{error:'Onbekende connector'})}
      if(req.method==='PUT'||req.method==='POST'){const b=await body(req),all=loadOverrides(),base=profiles()[id]||{id,naam:b.naam||id};all[id]={...base,...b,id};saveOverrides(all);return send(res,200,{ok:true,profile:all[id]})}
    }
    if(m&&m[1]==='config'){
      const id=decodeURIComponent(m[2]),c=ctx(req);if(req.method==='GET'){const p=profiles()[id];if(!p)return send(res,404,{error:'Onbekende connector'});const cfg=readConfig(c,id);return send(res,200,{ok:true,profile:p,configured:Boolean(Object.keys(cfg.credentials||{}).length||Object.keys(cfg.tokens||{}).length),credential_fields:p.credential_fields||[],config:{credentials:Object.fromEntries(Object.entries(cfg.credentials||{}).map(([k,v])=>[k,/secret|password|token|key/i.test(k)?'••••••••':v]))}})}
      if(req.method==='POST'||req.method==='PUT'){const b=await body(req),old=readConfig(c,id);writeConfig(c,id,{...old,credentials:{...(old.credentials||{}),...(b.credentials||{})},profile_overrides:{...(old.profile_overrides||{}),...(b.profile_overrides||{})}});return send(res,200,{ok:true,id})}
      if(req.method==='DELETE'){removeConfig(c,id);return send(res,200,{ok:true,id,removed:true})}
    }
    if(m&&m[1]==='test'&&req.method==='POST'){const id=decodeURIComponent(m[2]),s=await status(ctx(req),id);return send(res,200,{ok:true,connector:s})}
    if(m&&m[1]==='sync'&&req.method==='POST'){try{return send(res,200,await sync(ctx(req),decodeURIComponent(m[2])))}catch(e){return send(res,502,{error:e.message})}}
    const om=u.pathname.match(/^\/api\/connector-runtime\/oauth\/([^/]+)\/(start|callback)$/);if(om){const id=decodeURIComponent(om[1]);if(om[2]==='start')return oauthStart(req,res,id,u);return oauthCallback(req,res,id,u)}
    if(u.pathname==='/api/connector-runtime/status'&&req.method==='GET'){const c=ctx(req),ps=profiles(),rows=[];for(const id of Object.keys(ps))rows.push(await status(c,id));return send(res,200,{ok:true,total:rows.length,configured:rows.filter(x=>x.configured).length,connected:rows.filter(x=>x.connected).length,connectors:rows})}
    return false;
  }
  return {handle,profiles,status,readConfig,writeConfig};
}

