function seal(value){ const k=encKey(); if(!k) return {encrypted:false,data:value}; const iv=crypto.randomBytes(12), cipher=crypto.createCipheriv('aes-256-gcm',k,iv); const out=Buffer.concat([cipher.update(JSON.stringify(value),'utf8'),cipher.final()]); return {encrypted:true,iv:iv.toString('base64'),tag:cipher.getAuthTag().toString('base64'),data:out.toString('base64')}; }
function unseal(blob){ if(!blob) return null; if(blob.encrypted===false) return blob.data; const k=encKey(); if(!k) throw new Error('GOOGLE_TOKEN_ENCRYPTION_KEY ontbreekt'); const d=crypto.createDecipheriv('aes-256-gcm',k,Buffer.from(blob.iv,'base64')); d.setAuthTag(Buffer.from(blob.tag,'base64')); return JSON.parse(Buffer.concat([d.update(Buffer.from(blob.data,'base64')),d.final()]).toString('utf8')); }
function loadGoogle(c){ try{return unseal(JSON.parse(fs.readFileSync(googleFile(c),'utf8')))}catch{return null} }
function saveGoogle(c,v){ fs.writeFileSync(googleFile(c),JSON.stringify(seal(v),null,2)); googleCache.delete(key(c,'google-status')); }
function removeGoogle(c){ try{fs.unlinkSync(googleFile(c))}catch{} googleCache.delete(key(c,'google-status')); }
function origin(req){ const proto=String(req.headers['x-forwarded-proto']||'https').split(',')[0].trim(); return `${proto}://${req.headers.host}`; }
function googleConfig(){ return {client_id:process.env.GOOGLE_CLIENT_ID||'',client_secret:process.env.GOOGLE_CLIENT_SECRET||'',developer_token:process.env.GOOGLE_ADS_DEVELOPER_TOKEN||'',login_customer_id:String(process.env.GOOGLE_ADS_LOGIN_CUSTOMER_ID||'').replace(/-/g,''),redirect_uri:process.env.GOOGLE_REDIRECT_URI||''}; }
function stateSecret(){ const g=googleConfig(); return process.env.GOOGLE_OAUTH_STATE_SECRET||process.env.FOUNDLY_ENCRYPTION_KEY||g.client_secret||'foundly-dev-state'; }
function signState(payload){ const raw=Buffer.from(JSON.stringify(payload)).toString('base64url'); const sig=crypto.createHmac('sha256',stateSecret()).update(raw).digest('base64url'); return `${raw}.${sig}`; }
function parseState(state){ const [raw,sig]=String(state||'').split('.'); if(!raw||!sig)throw new Error('Ongeldige OAuth state'); const exp=crypto.createHmac('sha256',stateSecret()).update(raw).digest('base64url'); if(sig.length!==exp.length||!crypto.timingSafeEqual(Buffer.from(sig),Buffer.from(exp)))throw new Error('OAuth state verificatie mislukt'); const p=JSON.parse(Buffer.from(raw,'base64url').toString('utf8')); if(Date.now()-Number(p.ts||0)>15*60*1000)throw new Error('OAuth state verlopen'); return p; }
async function googleAccess(c){ const g=googleConfig(), saved=loadGoogle(c); if(!saved?.refresh_token&&!saved?.access_token) throw new Error('Google is niet gekoppeld'); if(saved.access_token&&Number(saved.expires_at||0)>Date.now()+60000)return saved.access_token; if(!saved.refresh_token)throw new Error('Google refresh token ontbreekt'); const r=await fetch('https://oauth2.googleapis.com/token',{method:'POST',headers:{'content-type':'application/x-www-form-urlencoded'},body:new URLSearchParams({client_id:g.client_id,client_secret:g.client_secret,refresh_token:saved.refresh_token,grant_type:'refresh_token'})}); const j=await r.json(); if(!r.ok)throw new Error(`Google token refresh ${r.status}: ${j.error_description||j.error||'mislukt'}`); const next={...saved,...j,refresh_token:saved.refresh_token,expires_at:Date.now()+Number(j.expires_in||3600)*1000}; saveGoogle(c,next); return next.access_token; }
async function gfetch(c,url,opts={}){ const token=await googleAccess(c); const headers={...(opts.headers||{}),authorization:`Bearer ${token}`}; const r=await fetch(url,{...opts,headers}); const text=await r.text(); let data; try{data=text?JSON.parse(text):{}}catch{data={raw:text}} if(!r.ok)throw new Error(`${r.status} ${data.error?.message||data.error_description||data.error||text||'Google API fout'}`); return data; }
async function probeGoogle(c,force=false){ const ck=key(c,'google-status'),cached=googleCache.get(ck); if(!force&&cached&&Date.now()-cached.at<60000)return cached.value; const cfg=googleConfig(), saved=loadGoogle(c); const base={oauth_configured:Boolean(cfg.client_id&&cfg.client_secret),token_stored:Boolean(saved?.refresh_token||saved?.access_token),storage_encrypted:Boolean(encKey()),account:saved?.account||null,services:{google_ads:false,ga4:false,search_console:false,google_calendar:false},errors:{}}; if(!base.oauth_configured||!base.token_stored){googleCache.set(ck,{at:Date.now(),value:base});return base;} try{await gfetch(c,'https://openidconnect.googleapis.com/v1/userinfo');}catch(e){base.errors.identity=e.message;googleCache.set(ck,{at:Date.now(),value:base});return base;}
  for(const [name,url,headers] of [
    ['ga4','https://analyticsadmin.googleapis.com/v1beta/accountSummaries?pageSize=1',{}],
    ['search_console','https://www.googleapis.com/webmasters/v3/sites',{}],
    ['google_calendar','https://www.googleapis.com/calendar/v3/users/me/calendarList?maxResults=1',{}],
    ['google_ads','https://googleads.googleapis.com/v25/customers:listAccessibleCustomers',cfg.developer_token?{'developer-token':cfg.developer_token,...(cfg.login_customer_id?{'login-customer-id':cfg.login_customer_id}:{})}:null]
  ]){ if(name==='google_ads'&&!headers){base.errors[name]='GOOGLE_ADS_DEVELOPER_TOKEN ontbreekt';continue} try{await gfetch(c,url,{headers});base.services[name]=true}catch(e){base.errors[name]=e.message} }
  base.connected=Object.values(base.services).some(Boolean); base.connected_count=Object.values(base.services).filter(Boolean).length; googleCache.set(ck,{at:Date.now(),value:base}); return base; }
async function openaiWebSearch(query,c){ const apiKey=process.env.OPENAI_API_KEY||process.env.FOUNDLY_AI_API_KEY; if(!apiKey)throw new Error('OPENAI_API_KEY ontbreekt'); const model=process.env.FOUNDLY_SEARCH_MODEL||process.env.FOUNDLY_AI_MODEL||'gpt-5'; const input=`Je bent Foundly Search Intelligence voor de Nederlandse automotive markt. Zoek actueel op het web en geef feitelijke, brongebonden informatie. Verzin geen zoekvolumes of marktdata. Vraag: ${query}`; const r=await fetch('https://api.openai.com/v1/responses',{method:'POST',headers:{'content-type':'application/json','authorization':`Bearer ${apiKey}`},body:JSON.stringify({model,input,tools:[{type:'web_search'}]})}); const j=await r.json(); if(!r.ok)throw new Error(`OpenAI web search ${r.status}: ${j.error?.message||'mislukt'}`); const text=j.output_text||((j.output||[]).flatMap(x=>x.content||[]).find(x=>x.type==='output_text')||{}).text||''; const sources=[]; for(const item of j.output||[]){ if(item.type==='web_search_call'&&item.action?.sources)for(const src of item.action.sources)sources.push(src); for(const part of item.content||[])for(const a of part.annotations||[])if(a.type==='url_citation')sources.push({type:'url',url:a.url,title:a.title}); }
  const rec={id:id(),at:new Date().toISOString(),query,text,sources:[...new Map(sources.filter(x=>x?.url).map(x=>[x.url,x])).values()]}; arr(records,key(c,'data')).push({_source:'openai_web_search',...rec}); return rec; }


