function signConnectorState(payload){const raw=Buffer.from(JSON.stringify(payload)).toString('base64url');const sig=crypto.createHmac('sha256',connectorStateSecret()).update(raw).digest('base64url');return `${raw}.${sig}`;}
function parseConnectorState(state){const [raw,sig]=String(state||'').split('.');if(!raw||!sig)throw new Error('Ongeldige OAuth state');const exp=crypto.createHmac('sha256',connectorStateSecret()).update(raw).digest('base64url');if(sig.length!==exp.length||!crypto.timingSafeEqual(Buffer.from(sig),Buffer.from(exp)))throw new Error('OAuth state verificatie mislukt');const p=JSON.parse(Buffer.from(raw,'base64url').toString('utf8'));if(Date.now()-Number(p.ts||0)>15*60*1000)throw new Error('OAuth state verlopen');return p;}
