async function simpleEnvStatus(id,c){
  const spec=CONNECTOR_REGISTRY[id]||{env:[]};
  const up=id.toUpperCase();
  const saved=loadConnector(c,id)||{};
  const req=spec.env||[];
  const envConfigured=req.length?req.every(k=>Boolean(process.env[k])):false;
  const baseUrl=saved.base_url||process.env[`${up}_BASE_URL`]||process.env[`${up}_API_URL`]||'';
  const hasSaved=Boolean(saved.api_key||saved.access_token||saved.username||saved.base_url||saved.webhook_url||saved.secret);
  const inherentlyPublic=['rdw','ecb_fx'].includes(id);
  const configured=inherentlyPublic||hasSaved||envConfigured||Boolean(baseUrl);
  const base={id,name:spec.naam||id,category:spec.categorie||'overig',auth:spec.auth||'configurable',configured,connected:false,status:configured?'geconfigureerd_niet_geverifieerd':'niet_geconfigureerd',error:null};
  if(inherentlyPublic&&!baseUrl){base.connected=true;base.status='publieke_bron_beschikbaar';return base;}
  if(!baseUrl)return base;
  try{
    const keyv=saved.api_key||saved.access_token||process.env[`${up}_API_KEY`]||process.env[`FOUNDLY_${up}_KEY`]||'';
    const authHeader=saved.auth_header||process.env[`${up}_AUTH_HEADER`]||'authorization';
    const prefix=saved.auth_prefix??process.env[`${up}_AUTH_PREFIX`]??'Bearer';
    const headers={...(saved.headers||{})}; if(keyv)headers[authHeader]=prefix?`${prefix} ${keyv}`:keyv;
    const health=saved.health_path||process.env[`${up}_HEALTH_PATH`]||'';
    const r=await fetch(baseUrl.replace(/\/$/,'')+health,{method:saved.health_method||'GET',headers});
    base.connected=r.ok;base.status=r.ok?'verbonden':'healthcheck_mislukt';if(!r.ok)base.error=`HTTP ${r.status}`;
  }catch(e){base.error=e.message}
  return base;
}
async function universalStatuses(c,force=false){
  const gs=await probeGoogle(c,force),[meta,linkedin,tiktok,whatsapp,email,voice,dms,webhooks]=await Promise.all([probeMeta(c,force),probeLinkedIn(c,force),probeTikTok(c,force),probeWhatsApp(),probeEmail(),probeVoice(),probeDms(),probeWebhook()]);
  const googleIds=new Set(['google_ads','ga4','search_console','google_calendar']); const list=[];
  for(const cid of CONNECTORS){
    const spec=CONNECTOR_REGISTRY[cid]||{};
    if(googleIds.has(cid)){const connected=Boolean(gs.services[cid]);list.push({id:cid,name:spec.naam,category:spec.categorie,auth:spec.auth,configured:gs.oauth_configured,connected,status:connected?'verbonden':(gs.token_stored?'gekoppeld_api_niet_beschikbaar':(gs.oauth_configured?'klaar_voor_oauth':'niet_geconfigureerd')),error:gs.errors[cid]||null});continue}
    if(cid==='openai'){const configured=Boolean(process.env.OPENAI_API_KEY||process.env.FOUNDLY_AI_API_KEY);let connected=false,error=null;if(configured){try{const r=await fetch('https://api.openai.com/v1/models',{headers:{authorization:`Bearer ${process.env.OPENAI_API_KEY||process.env.FOUNDLY_AI_API_KEY}`}});connected=r.ok;if(!r.ok)error=`HTTP ${r.status}`}catch(e){error=e.message}}list.push({id:cid,name:spec.naam,category:spec.categorie,auth:spec.auth,configured,connected,status:connected?'verbonden':(configured?'api_key_niet_geverifieerd':'niet_geconfigureerd'),error});continue}
    if(cid==='meta'){list.push({...meta,name:spec.naam,category:spec.categorie,auth:spec.auth});continue}
    if(cid==='instagram'){list.push({id:'instagram',name:spec.naam,category:spec.categorie,auth:spec.auth,configured:meta.configured,connected:Boolean(meta.services.instagram),status:meta.services.instagram?'verbonden':(meta.connected?'meta_verbonden_geen_instagram_business':'niet_verbonden'),error:meta.error});continue}
    if(cid==='facebook_pages'){list.push({id:cid,name:spec.naam,category:spec.categorie,auth:spec.auth,configured:meta.configured,connected:Boolean(meta.connected&&meta.pages>0),status:meta.connected?(meta.pages>0?'verbonden':'geen_pages_gevonden'):'niet_verbonden',error:meta.error});continue}
    if(cid==='meta_pixel'||cid==='meta_capi'){list.push(await simpleEnvStatus(cid,c));continue}
    if(cid==='linkedin'){list.push({...linkedin,name:spec.naam,category:spec.categorie,auth:spec.auth});continue}
    if(cid==='tiktok'){list.push({...tiktok,name:spec.naam,category:spec.categorie,auth:spec.auth});continue}
    if(cid==='whatsapp'){list.push({...whatsapp,name:spec.naam,category:spec.categorie,auth:spec.auth});continue}
    if(cid==='email'){list.push({...email,name:spec.naam,category:spec.categorie,auth:spec.auth});continue}
    if(cid==='voice'){list.push({...voice,name:spec.naam,category:spec.categorie,auth:spec.auth});continue}
    if(cid==='dms'){list.push({...dms,name:spec.naam,category:spec.categorie,auth:spec.auth});continue}
    if(cid==='webhooks'){list.push({...webhooks,name:spec.naam,category:spec.categorie,auth:spec.auth});continue}
    list.push(await simpleEnvStatus(cid,c));
  }
  return {list,google:gs,meta,linkedin,tiktok,whatsapp,email,voice,dms,webhooks};
}


