function arr(map,k){ if(!map.has(k)) map.set(k,[]); return map.get(k); }
function id(){ return crypto.randomUUID ? crypto.randomUUID() : crypto.randomBytes(16).toString('hex'); }
function json(res,status,obj){ res.writeHead(status,{'content-type':'application/json; charset=utf-8','cache-control':'no-store','access-control-allow-origin':'*','access-control-allow-headers':'content-type,x-foundly-tenant,x-foundly-dealer'}); res.end(JSON.stringify(obj)); }
